	gap: 8px;
}
.rooms-editor__field--checkbox > input[type="checkbox"][data-v-23dfd052] {
	width: auto !important;
	margin: 0 !important;
}
.rooms-editor__label[data-v-23dfd052] {
	display: block !important;
	font-size: 13px;
	font-weight: 500;
	margin: 0 0 4px 0 !important;
}
.rooms-editor__label--inline[data-v-23dfd052] {
	display: inline-block !important;
